ps.pstext:
if !IsFeatureImplemented(FEAT_SME_F8F32) then EndOfDecode(Decode_UNDEF); end;
let a : integer = UInt(Pn);
let b : integer = UInt(Pm);
let n : integer = UInt(Zn);
let m : integer = UInt(Zm);
let da : integer = UInt(ZAda);

CheckFPMREnabled();
CheckStreamingSVEAndZAEnabled();
let VL : integer{} = CurrentVL();
let PL : integer{} = VL DIV 8;
let dim : integer{} = VL DIV 32;
let mask1 : bits(PL) = P{PL}(a);
let mask2 : bits(PL) = P{PL}(b);
let operand1 : bits(VL) = Z{VL}(n);
let operand2 : bits(VL) = Z{VL}(m);
let operand3 : bits(dim*dim*32) = ZAtile{dim*dim*32}(da, 32);
var result : bits(dim*dim*32);

for row = 0 to dim-1 do
    for col = 0 to dim-1 do
        var prow : array [[4]] of boolean;
        var pcol : array [[4]] of boolean;
        var any_active : boolean = FALSE;
        for i = 0 to 3 do
            prow[[i]] = ActivePredicateElement{PL}(mask1, 4*row + i, 8);
            pcol[[i]] = ActivePredicateElement{PL}(mask2, 4*col + i, 8);
            any_active = any_active || (prow[[i]] && pcol[[i]]);
        end;

        if any_active then
            var sum : bits(32) = operand3[(row*dim+col)*:32];
            var rowop : bits(32) = Zeros{};
            var colop : bits(32) = Zeros{};
            for i = 0 to 3 do
                if prow[[i]] then
                    rowop[i*:8] = operand1[(4*row + i)*:8];
                end;
                if pcol[[i]] then
                    colop[i*:8] = operand2[(4*col + i)*:8];
                end;
            end;

            sum = FP8DotAddFP{32, 32}(sum, rowop, colop, FPCR(), FPMR());
            result[(row*dim+col)*:32] = sum;
        else
            result[(row*dim+col)*:32] = operand3[(row*dim+col)*:32];
        end;
    end;
end;

ZAtile{dim*dim*32}(da, 32) = result;
